mapper.select:
WITH charge_kpi AS ( SELECT IFNULL(SUM(CASE WHEN cr.channel NOT IN ('REDPACKET_GET_PAY', 'PROXY_PAY') THEN cr.amount_usd ELSE 0 END), 0) AS chargeAmount, IFNULL(SUM(CASE WHEN cr.channel != 'REDPACKET_GET_PAY' THEN cr.total_gold ELSE 0 END), 0) / 10000 AS saleAmount FROM charge_record cr
WHERE cr.charge_status = 2 AND cr.create_time BETWEEN #{startTime} AND #{endTime}
), proxy_charge_kpi AS ( SELECT IFNULL(SUM(cpr.amount_usd), 0) AS proxyChargeAmount FROM charge_proxy_record cpr
WHERE cpr.charge_status = 2 AND cpr.create_time BETWEEN #{startTime} AND #{endTime}
), gift_kpi AS ( SELECT IFNULL(SUM(bg.gold_num), 0) AS giftGold FROM bill_gold bg
WHERE bg.type = 2 AND bg.bill_type IN (30, 36, 37) AND bg.create_time BETWEEN #{startTime} AND #{endTime}
), room_kpi AS ( SELECT COUNT(0) AS onlineRooms, IFNULL(SUM(r.online_num), 0) AS onlineUsers FROM fm_room r
WHERE r.online_num > 0
) SELECT (SELECT COUNT(DISTINCT alr.uid) FROM account_login_record alr
WHERE alr.create_time BETWEEN #{startTime} AND #{endTime} ) AS dau, (SELECT COUNT(DISTINCT a.uid) FROM account a
WHERE a.register_date BETWEEN DATE(#{startTime}) AND DATE(#{endTime}) ) AS dnu, charge_kpi.chargeAmount + proxy_charge_kpi.proxyChargeAmount AS gmv, charge_kpi.saleAmount AS netRevenue, gift_kpi.giftGold AS giftGold, room_kpi.onlineRooms AS onlineRooms, room_kpi.onlineUsers AS onlineUsers FROM charge_kpi CROSS JOIN proxy_charge_kpi CROSS JOIN gift_kpi CROSS JOIN room_kpi

WITH RECURSIVE days AS ( SELECT DATE(#{startTime}) AS stat_date UNION ALL SELECT DATE_ADD(stat_date, INTERVAL 1 DAY) FROM days WHERE stat_date < DATE(#{endTime}) ), charge_daily AS ( SELECT DATE(cr.create_time) AS stat_date, IFNULL(SUM(cr.amount_usd), 0) AS gmv FROM charge_record cr
WHERE cr.charge_status = 2 AND cr.channel NOT IN ('REDPACKET_GET_PAY', 'PROXY_PAY') AND cr.create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE(cr.create_time) ), proxy_charge_daily AS ( SELECT DATE(cpr.create_time) AS stat_date, IFNULL(SUM(cpr.amount_usd), 0) AS gmv FROM charge_proxy_record cpr
WHERE cpr.charge_status = 2 AND cpr.create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE(cpr.create_time) ), login_daily AS ( SELECT DATE(alr.create_time) AS stat_date, COUNT(DISTINCT alr.uid) AS dau FROM account_login_record alr
WHERE alr.create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY DATE(alr.create_time) ) SELECT DATE_FORMAT(days.stat_date, '%Y-%m-%d') AS statDate, IFNULL(charge_daily.gmv, 0) + IFNULL(proxy_charge_daily.gmv, 0) AS gmv, IFNULL(login_daily.dau, 0) AS dau FROM days LEFT JOIN charge_daily ON charge_daily.stat_date = days.stat_date LEFT JOIN proxy_charge_daily ON proxy_charge_daily.stat_date = days.stat_date LEFT JOIN login_daily ON login_daily.stat_date = days.stat_date ORDER BY days.stat_date

WITH RECURSIVE time_points AS ( SELECT DATE_SUB(DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:00'), INTERVAL 55 MINUTE) AS stat_time UNION ALL SELECT DATE_ADD(stat_time, INTERVAL 5 MINUTE) FROM time_points WHERE stat_time < DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:00') ), online_sessions AS ( SELECT uot.uid, uot.create_time, uot.update_time FROM user_online_time uot
WHERE uot.region_id = #{query.regionId} AND uot.create_time <= NOW() AND (uot.update_time IS NULL OR uot.update_time >= DATE_SUB(NOW(), INTERVAL 55 MINUTE))
AND u.country = #{query.country}
AND u.app = #{query.channel}
) SELECT DATE_FORMAT(tp.stat_time, '%H:%i') AS statTime, COUNT(DISTINCT os.uid) AS onlineUsers FROM time_points tp LEFT JOIN online_sessions os ON os.create_time <= tp.stat_time AND (os.update_time IS NULL OR os.update_time >= tp.stat_time) GROUP BY tp.stat_time ORDER BY tp.stat_time

SELECT IFNULL(NULLIF(u.country, ''), '未知') AS country, IFNULL(SUM(cr.amount_usd), 0) AS amount, COUNT(DISTINCT cr.uid) AS payUsers FROM charge_record cr JOIN `user` u ON u.uid = cr.uid AND u.region_id = cr.region_id WHERE cr.charge_status = 2 AND cr.channel NOT IN ('REDPACKET_GET_PAY', 'PROXY_PAY') AND cr.create_time BETWEEN #{startTime} AND #{endTime} AND u.region_id = #{query.regionId}
AND u.country = #{query.country}
AND u.app = #{query.channel}
GROUP BY u.country ORDER BY amount DESC LIMIT 8
